import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    nums = list(map(int, data))
    # Expect exactly 18 numbers for two 3x3 matrices
    if len(nums) < 18:
        return
    A = [nums[i*3:(i+1)*3] for i in range(3)]
    B = [nums[9 + i*3:9 + (i+1)*3] for i in range(3)]

    C = [[0]*3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            total = 0
            for k in range(3):
                total += A[i][k] * B[k][j]
            C[i][j] = total

    out = '\n'.join(' '.join(map(str, row)) for row in C)
    sys.stdout.write(out)

if __name__ == "__main__":
    solve()
